<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import StateCard from'../../Components/StateCard.vue';import UiButton from'../../Components/UiButton.vue';import{Head,router}from'@inertiajs/vue3';defineProps({event:Object,reviews:Array});function decide(id,decision){router.post(`/face-matches/${id}/review`,{decision},{preserveScroll:true,onSuccess:()=>router.reload({only:['reviews']})})}</script><template><AppShell><Head title="Manual face review"/><div class="lp-page"><PageHeader eyebrow="Authorized review" :title="`Manual review · ${event.name}`" description="Only authorized event managers can confirm or reject candidates."><UiButton variant="secondary" :href="`/groups/${event.id}`">Event workspace</UiButton></PageHeader><StateCard v-if="!reviews.length" class="mt-8" title="Review queue is clear" message="No face-match candidates currently require a decision." tone="success"/><div v-else class="photo-grid mt-8 grid grid-cols-2 gap-1 md:grid-cols-3 xl:grid-cols-4"><figure v-for="r in reviews" :key="r.id" class="photo-tile bg-white"><img :src="r.photo_url" alt="Face-match candidate" class="aspect-[4/3] w-full object-cover"><figcaption class="border border-t-0 border-slate-200 p-3"><p class="text-sm font-semibold">{{r.similarity.toFixed(1)}}% similarity</p><div class="mt-3 flex gap-2"><button class="btn-primary flex-1" @click="decide(r.id,'confirmed')">Confirm</button><button class="btn-danger flex-1" @click="decide(r.id,'rejected')">Reject</button></div></figcaption></figure></div></div></AppShell></template>
